package api

import (
	"testing"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
	_ "modernc.org/sqlite"
)

func TestDiagnoseLockFailurePoint(t *testing.T) {
	_, harness := newVisibilityRouter(t)

	// connection 2: hold the reserved writer lock via a fixture INSERT.
	holder, err := harness.Begin()
	if err != nil {
		t.Fatalf("holder begin: %v", err)
	}
	if _, err := holder.Exec(
		`INSERT INTO service_metadata (key, value) VALUES ('diag', 'held')`); err != nil {
		t.Fatalf("holder insert: %v", err)
	}
	defer holder.Rollback()
	waitForPendingWriteLock(t, harness)

	// A committed row exists so the identity SELECT has something to read.
	// Probe with a third independent connection.
	probe, err := storeOpenProbe(t)
	if err != nil {
		t.Fatal(err)
	}
	defer probe.Close()

	// 1. Plain deferred BEGIN while writer is held.
	tx, err := probe.Begin()
	t.Logf("probe BEGIN: err=%v", err)
	if err != nil {
		t.Fatalf("BEGIN itself failed: %v", err)
	}
	defer tx.Rollback()

	// 2. Identity read inside the deferred transaction (WAL: readers allowed).
	var id int
	err = tx.QueryRow(`SELECT id FROM artifacts WHERE repository = ? AND digest = ?`,
		sequenceRepo, testDigestB).Scan(&id)
	t.Logf("identity SELECT for absent B: err=%v", err)

	var n int
	err = tx.QueryRow(`SELECT count(*) FROM artifacts WHERE repository = ?`, sequenceRepo).Scan(&n)
	t.Logf("identity SELECT count over committed A: n=%d err=%v", n, err)

	// 3. The write the new-artifact branch needs.
	_, err = tx.Exec(
		`INSERT INTO artifacts (repository, digest, tag, signature_verified, retention_days, size_bytes, pushed_at)
		 VALUES (?, ?, ?, ?, ?, ?, ?)`,
		sequenceRepo, testDigestB, sequenceTag, 1, regRetention, regSizeB, "now")
	t.Logf("INSERT B while lock held: err=%v", err)
}

